@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #3730a3;
  --primary-dark: #312e81;
  --primary-light: #e0e7ff;
  --accent: #f43f5e;
  --accent-hover: #e11d48;
  --success: #10b981;
  --bg-main: #ffffff;
  --bg-alt: #f8fafc;
  --text-main: #0f172a;
  --text-muted: #475569;
  --border: #e2e8f0;

  --font-family: 'Inter', sans-serif;
  --radius: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
  --transition: all 0.3s ease;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: var(--font-family); color: var(--text-main); background: var(--bg-main); line-height: 1.6; overflow-x: hidden; }
h1, h2, h3, h4, h5, h6 { font-weight: 800; line-height: 1.2; letter-spacing: -0.02em; color: var(--text-main); }
a { text-decoration: none; color: inherit; transition: var(--transition); }
ul { list-style: none; }
img { max-width: 100%; height: auto; display: block; border-radius: 8px; }

/* Layout */
.container { width: 100%; max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.section { padding: 96px 0; }
.section-alt { background-color: var(--bg-alt); }
.text-center { text-align: center; }
.mb-2 { margin-bottom: 8px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }
.mb-8 { margin-bottom: 32px; }
.mb-12 { margin-bottom: 48px; }

/* Typography */
.h1 { font-size: 3.5rem; margin-bottom: 24px; }
.h2 { font-size: 2.75rem; margin-bottom: 16px; }
.h3 { font-size: 1.75rem; margin-bottom: 16px; }
.subtitle { font-size: 1.25rem; color: var(--text-muted); margin-bottom: 32px; max-width: 768px; margin-left: auto; margin-right: auto; }
.text-accent { color: var(--accent); }
.text-primary { color: var(--primary); }

/* Navigation */
.navbar { position: fixed; top: 0; width: 100%; background: rgba(255,255,255,0.95); backdrop-filter: blur(8px); z-index: 1000; border-bottom: 1px solid var(--border); }
.nav-container { display: flex; align-items: center; justify-content: space-between; height: 80px; }
.logo { font-size: 1.5rem; font-weight: 800; color: var(--primary-dark); display: flex; align-items: center; gap: 8px; }
.logo-icon { width: 32px; height: 32px; background: var(--primary); border-radius: 8px; display: inline-block; }
.nav-links { display: flex; gap: 32px; align-items: center; }
.nav-links a { font-weight: 600; color: var(--text-muted); }
.nav-links a:hover, .nav-links a.active { color: var(--primary); }
.nav-actions { display: flex; gap: 16px; align-items: center; }

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; padding: 14px 28px; border-radius: 8px; font-weight: 600; cursor: pointer; transition: var(--transition); border: 2px solid transparent; font-size: 1rem; }
.btn-primary { background: var(--primary); color: white; }
.btn-primary:hover { background: var(--primary-dark); box-shadow: var(--shadow-md); transform: translateY(-2px); }
.btn-accent { background: var(--accent); color: white; }
.btn-accent:hover { background: var(--accent-hover); box-shadow: var(--shadow-md); transform: translateY(-2px); }
.btn-outline { background: transparent; border-color: var(--primary); color: var(--primary); }
.btn-outline:hover { background: var(--primary-light); }

/* Hero Section */
.hero { padding: 180px 0 96px; text-align: center; background: linear-gradient(135deg, var(--bg-alt) 0%, #ffffff 100%); }
.hero-content { max-width: 800px; margin: 0 auto; }
.hero-visual { margin-top: 64px; position: relative; perspective: 1000px; }

/* Tabs */
.tab-group { width: 100%; }
.tab-buttons { display: flex; justify-content: center; gap: 16px; margin-bottom: 48px; flex-wrap: wrap; }
.tab-btn { background: var(--bg-main); border: 1px solid var(--border); padding: 12px 24px; border-radius: 30px; font-weight: 600; color: var(--text-muted); cursor: pointer; transition: var(--transition); }
.tab-btn:hover { border-color: var(--primary); color: var(--primary); }
.tab-btn.active { background: var(--primary); color: white; border-color: var(--primary); box-shadow: var(--shadow-md); }
.tab-content { display: none; animation: fadeIn 0.4s ease; }
.tab-content.active { display: block; }

/* Stats Bar */
.stats-bar { background: var(--primary-dark); color: white; padding: 64px 0; }
.stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 32px; text-align: center; }
.stat-number { font-size: 4rem; font-weight: 800; color: var(--accent); margin-bottom: 8px; line-height: 1;}
.stat-label { font-size: 1.125rem; font-weight: 600; opacity: 0.9; }

/* Cards & Grids */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.card { background: white; border-radius: var(--radius); padding: 32px; box-shadow: var(--shadow-md); border: 1px solid var(--border); transition: var(--transition); height: 100%; display: flex; flex-direction: column; }
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: var(--primary-light); }
.card-icon { width: 56px; height: 56px; background: var(--primary-light); color: var(--primary); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 1.75rem; margin-bottom: 24px; }
.card-title { font-size: 1.25rem; font-weight: 700; margin-bottom: 12px; }
.card-list { list-style: none; margin-top: 24px; border-top: 1px solid var(--border); padding-top: 24px; }
.card-list li { margin-bottom: 12px; display: flex; align-items: center; gap: 12px; color: var(--text-muted); }
.card-list li::before { content: "✓"; color: var(--success); font-weight: 700; }

/* Logos */
.logo-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 32px; align-items: center; justify-items: center; opacity: 0.5; }
.logo-item { font-size: 1.5rem; font-weight: 800; color: var(--text-muted); }

/* Carousels */
.carousel { position: relative; overflow: hidden; padding: 24px 0; }
.carousel-track { display: flex; transition: transform 0.5s ease; }
.carousel-slide { min-width: 100%; padding: 0 16px; flex-shrink: 0; }
.testimonial-card { background: white; border-radius: var(--radius); padding: 48px; box-shadow: var(--shadow-md); border: 1px solid var(--border); text-align: center; max-width: 800px; margin: 0 auto; }
.testimonial-quote { font-size: 1.5rem; font-style: italic; margin-bottom: 32px; color: var(--text-muted); font-weight: 500; }
.testimonial-author { font-weight: 800; color: var(--primary-dark); font-size: 1.125rem; }
.testimonial-role { font-size: 1rem; color: var(--text-muted); }
.carousel-nav { display: flex; justify-content: center; gap: 16px; margin-top: 32px; }
.carousel-btn { width: 48px; height: 48px; border-radius: 50%; background: white; border: 1px solid var(--border); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: var(--transition); box-shadow: var(--shadow-sm); font-size: 1.25rem; }
.carousel-btn:hover { background: var(--primary); color: white; border-color: var(--primary); }

/* Accordion */
.accordion-group { max-width: 800px; margin: 0 auto; }
.accordion-item { border: 1px solid var(--border); border-radius: 12px; margin-bottom: 16px; background: white; overflow: hidden; }
.accordion-header { padding: 24px; display: flex; justify-content: space-between; align-items: center; cursor: pointer; font-weight: 600; font-size: 1.125rem; transition: var(--transition); }
.accordion-header:hover { background: var(--bg-alt); }
.accordion-header.active { color: var(--primary); border-bottom: 1px solid var(--border); }
.accordion-icon { transition: transform 0.3s ease; font-size: 0.875rem; }
.accordion-header.active .accordion-icon { transform: rotate(180deg); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.4s ease; background: white; }
.accordion-content { padding: 24px; color: var(--text-muted); line-height: 1.8; }

/* Tools Grid */
.tools-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; }
.tool-item { background: white; border: 1px solid var(--border); padding: 16px; border-radius: 12px; text-align: center; font-weight: 600; color: var(--primary-dark); box-shadow: var(--shadow-sm); }
.tool-item:hover { border-color: var(--primary); background: var(--primary-light); }

/* Footer */
.footer { background: #0f172a; color: white; padding: 96px 0 48px; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 64px; }
.footer-heading { font-size: 1.125rem; font-weight: 700; margin-bottom: 24px; color: white; }
.footer-links li { margin-bottom: 16px; }
.footer-links a { color: #94a3b8; font-weight: 500; }
.footer-links a:hover { color: white; }
.footer-bottom { border-top: 1px solid #1e293b; padding-top: 32px; display: flex; justify-content: space-between; align-items: center; color: #94a3b8; font-size: 0.875rem; }

/* CTA Banner */
.cta-banner { background: var(--primary); border-radius: 24px; padding: 80px 40px; text-align: center; color: white; box-shadow: var(--shadow-xl); position: relative; overflow: hidden; }
.cta-banner::before { content: ""; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%; background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%); z-index: 0; }
.cta-banner > * { position: relative; z-index: 1; }

/* Animations */
.fade-up { opacity: 0; transform: translateY(30px); transition: opacity 0.6s ease, transform 0.6s ease; }
.fade-up.animate-in { opacity: 1; transform: translateY(0); }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

/* Responsive */
@media (max-width: 992px) {
  .grid-3, .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-2 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .h1 { font-size: 3rem; }
  .h2 { font-size: 2.25rem; }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .h1 { font-size: 2.5rem; }
  .h2 { font-size: 2rem; }
  .section { padding: 64px 0; }
  .stats-grid { grid-template-columns: 1fr; }
  .cta-banner { padding: 48px 24px; border-radius: 16px; }
}

document.addEventListener('DOMContentLoaded', () => {
    // Tabs
    const tabGroups = document.querySelectorAll('.tab-group');
    tabGroups.forEach(group => {
        const btns = group.querySelectorAll('.tab-btn');
        const contents = group.querySelectorAll('.tab-content');
        btns.forEach(btn => {
            btn.addEventListener('click', () => {
                btns.forEach(b => b.classList.remove('active'));
                contents.forEach(c => c.classList.remove('active'));
                btn.classList.add('active');
                group.querySelector(`#${btn.dataset.target}`).classList.add('active');
            });
        });
    });

    // Accordions (FAQs and Product Demos)
    const accordions = document.querySelectorAll('.accordion-header');
    accordions.forEach(acc => {
        acc.addEventListener('click', () => {
            const body = acc.nextElementSibling;
            const isOpen = acc.classList.contains('active');

            const parent = acc.closest('.accordion-group');
            if(parent) {
                parent.querySelectorAll('.accordion-header').forEach(other => {
                    other.classList.remove('active');
                    other.nextElementSibling.style.maxHeight = null;
                });
            }

            if (!isOpen) {
                acc.classList.add('active');
                body.style.maxHeight = body.scrollHeight + "px";
            }
        });
    });

    // Carousels
    const carousels = document.querySelectorAll('.carousel');
    carousels.forEach(carousel => {
        const track = carousel.querySelector('.carousel-track');
        if (!track) return;
        const slides = Array.from(track.children);
        const nextBtn = carousel.querySelector('.carousel-next');
        const prevBtn = carousel.querySelector('.carousel-prev');
        let currentIndex = 0;

        const updateSlidePosition = () => {
            track.style.transform = `translateX(-${currentIndex * 100}%)`;
        };

        if(nextBtn && prevBtn) {
            nextBtn.addEventListener('click', () => {
                if(currentIndex < slides.length - 1) currentIndex++;
                else currentIndex = 0;
                updateSlidePosition();
            });
            prevBtn.addEventListener('click', () => {
                if(currentIndex > 0) currentIndex--;
                else currentIndex = slides.length - 1;
                updateSlidePosition();
            });
        }
    });

    // Scroll Animations
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if(entry.isIntersecting) {
                entry.target.classList.add('animate-in');
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.1 });

    document.querySelectorAll('.fade-up').forEach(el => observer.observe(el));
});
